"""Wythoff game: lexicographically smallest winning move."""


BLIM = 40


def _losing_table():
    # cold positions (a_n, b_n) with a_n < b_n, generated by mex rule,
    # covers all reachable positions with coordinates <= BLIM
    used = set()
    table = set()
    n = 0
    while True:
        a = 0
        while a in used:
            a += 1
        b = a + n
        if a > BLIM:
            break
        table.add((a, b))
        used.add(a)
        used.add(b)
        n += 1
    return table


_LOSING = _losing_table()


def _is_losing(a, b):
    if a > b:
        a, b = b, a
    return (a, b) in _LOSING


def solve(text: str) -> str:
    tokens = text.split()
    a, b = int(tokens[0]), int(tokens[1])

    if _is_losing(a, b):
        return 'LOSE'

    best = None
    for i in range(a + 1):
        for j in range(b + 1):
            if i == 0 and j == 0:
                continue
            if (i == 0) or (j == 0) or (i == j):
                if _is_losing(a - i, b - j):
                    if best is None or (i, j) < best:
                        best = (i, j)
    return 'WIN %d %d' % best
